INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Стратегическое планирование','Правительство определило стратегические приоритеты и целевые ориентиры развития на следующий период. Какая деятельность осуществлена?','["Программирование","Контроль исполнения","Методическое обеспечение","Целеполагание"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Целеполагание устанавливает направления, цели и приоритеты развития и безопасности.',true),
('Стратегическое планирование','Эксперты подготовили научно обоснованные сценарии рисков региональной экономики. Какая стадия стратегического планирования здесь представлена?','["Целеполагание","Программирование","Прогнозирование","Государственная регистрация"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Прогнозирование включает научно обоснованные представления о рисках, угрозах и результатах развития.',true),
('Стратегическое планирование','Власти разработали комплекс взаимосвязанных мероприятий с исполнителями, ресурсами и сроками в рамках государственной программы. Как называется соответствующая деятельность?','["Только целеполагание","Программирование","Судебный контроль","Нормативное толкование"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Программирование связано с разработкой и реализацией государственных и муниципальных программ.',true),
('Стратегическое планирование','Федеральное ведомство подготовило план своей деятельности для достижения целей утверждённой стратегии. К какой деятельности это относится?','["Планирование","Мониторинг","Государственная регистрация","Только целеполагание"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Планирование включает разработку основных направлений деятельности Правительства и планов федеральных органов.',true),
('Стратегическое планирование','Субъект РФ изменил показатели стратегии, оставив неизменным период её действия. Как это квалифицирует 172-ФЗ?','["Первичная разработка новой стратегии","Отмена стратегического планирования","Формирование нового субъекта РФ","Корректировка документа стратегического планирования"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Корректировка меняет документ без изменения периода его действия.',true),
('Стратегическое планирование','Какой срок 172-ФЗ относит к среднесрочному периоду?','["Один календарный месяц","От одного года до двух лет включительно","От трёх до шести лет включительно после текущего года","Более шести лет после текущего года"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Пункт 19 статьи 3 определяет среднесрочный период как срок от трёх до шести лет.',true),
('Стратегическое планирование','Каков долгосрочный период в терминологии 172-ФЗ?','["От трёх до шести лет","Более шести лет после текущего года","Только следующий календарный год","Не более одного финансового года"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Пункт 20 статьи 3 относит к долгосрочному периоду более шести лет.',true),
('Стратегическое планирование','Что считается отчётным периодом для целей стратегического планирования?','["Отчётный год и два предшествующих ему года","Только отчётный год","Текущий год и пять последующих лет","Любой произвольный период"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Пункт 18 статьи 3 охватывает отчётный год и два года, ему предшествовавших.',true),
('Стратегическое планирование','В министерстве перепутали отчётный и текущий годы. Как определяется отчётный год по 172-ФЗ?','["Первый год после текущего","Любые двенадцать месяцев по выбору ведомства","Последние три финансовых года","Календарный год, предшествующий текущему"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Пункт 17 статьи 3 закрепляет календарный год с 1 января по 31 декабря, предшествующий текущему.',true),
('Стратегическое планирование','Проект содержит ориентир желаемого состояния экономики, выраженный количественными и качественными показателями. Как это называется?','["Бюджетное нарушение","Дисциплинарное взыскание","Цель социально-экономического развития","Отчётный период"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Цель — состояние экономики или социальной сферы, избираемое участниками как ориентир.',true),
('Стратегическое планирование','Для достижения установленной цели составлен взаимосвязанный комплекс мероприятий на определённый срок. Что это?','["Показатель инфляции сам по себе","Задача социально-экономического развития","Государственная должность","Произвольный отчёт"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Задача — комплекс взаимосвязанных мероприятий, реализация которых обеспечивает достижение цели.',true),
('Стратегическое планирование','Что обозначает фактически достигнутое состояние экономики или социальной сферы, измеряемое показателями?','["Результат социально-экономического развития","Только стратегический приоритет","Проект без утверждения","Процесс назначения должностного лица"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Результат относится к фактически достигнутому состоянию, а не только планируемому.',true),
('Стратегическое планирование','К какой категории относится документ с научно обоснованными представлениями о стратегических рисках и угрозах национальной безопасности?','["Муниципальная программа благоустройства","Реестр должностей гражданской службы","План закупок частной компании","Стратегический прогноз Российской Федерации"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Стратегический прогноз содержит научно обоснованные оценки стратегических рисков и угроз.',true),
('Стратегическое планирование','Федеральный орган подготовил документ с ожидаемыми результатами научно-технологического развития на долгосрочный период. Как он называется?','["Отчёт об исполнении муниципального бюджета","Региональный устав","Прогноз научно-технологического развития Российской Федерации","Государственная программа вооружения"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Определение прогноза научно-технологического развития дано в пункте 22.',true),
('Стратегическое планирование','Что прежде всего содержит стратегия социально-экономического развития России по 172-ФЗ?','["Личный состав всех федеральных министерств","Долгосрочные приоритеты, цели и задачи государственного управления","Протоколы муниципальных выборов","Исключительно бюджетную отчётность за прошлый месяц"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Стратегия закрепляет долгосрочные приоритеты, цели и задачи государственного управления.',true),
('Стратегическое планирование','Документ задаёт приоритеты регионального развития страны и поддержания устойчивой системы расселения. Что это за документ?','["Стратегия пространственного развития Российской Федерации","Должностной регламент служащего","Отчёт о доходах государственных служащих","Исключительно федеральная адресная инвестиционная программа"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Стратегия пространственного развития направлена на региональное развитие и устойчивость системы расселения.',true),
('Стратегическое планирование','Как закон определяет макрорегион при подготовке стратегических документов?','["Любой один муниципальный район","Только федеральный округ с одним субъектом РФ","Исключительно территория города федерального значения","Часть территории, включающая два и более субъекта РФ и требующая выделения особых целей развития"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Макрорегион охватывает территории не менее двух субъектов РФ.',true),
('Стратегическое планирование','К какой категории относится программа региона, содержащая взаимосвязанные мероприятия с ресурсами и исполнителями для достижения региональных целей?','["Международный договор субъекта РФ","Федеральный конституционный закон","Государственная программа субъекта Российской Федерации","Индивидуальный должностной регламент"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Государственная программа субъекта соединяет мероприятия по задачам, срокам, исполнителям и ресурсам.',true),
('Стратегическое планирование','Что определяет стратегия социально-экономического развития муниципального образования?','["Исключительно штат органов федеральной власти","Долгосрочные цели и задачи муниципального управления и развития территории","Только численность муниципальных депутатов","Условия назначения мировых судей"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Муниципальная стратегия ориентирована на долгосрочные цели и задачи территории.',true),
('Стратегическое планирование','Что отличает национальный проект как документ стратегического планирования в редакции закона после 2024 года?','["Комплекс мероприятий для уникальных результатов при временных и ресурсных ограничениях","Бессрочный список пожеланий без измеримых результатов","Только устав политической партии","Исключительно бюджетная отчётность за предыдущий год"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Пункт 30.1 прямо указывает временные и ресурсные ограничения, уникальные результаты и национальные цели.',true),
('Стратегическое планирование','Стратегия научно-технологического развития нацелена прежде всего на какой временной горизонт?','["Только следующий месяц","Только один бюджетный квартал","Исключительно отчётный год","Долгосрочный"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Пункт 37 статьи 3 определяет долгосрочный характер стратегии научно-технологического развития.',true),
('Стратегическое планирование','Кто занимается муниципальным управлением в смысле закона о стратегическом планировании?','["Только Центральная избирательная комиссия","Исключительно федеральный кабинет министров","Органы местного самоуправления при реализации полномочий в социально-экономическом развитии","Только коммерческие компании региона"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Муниципальное управление связано с реализацией органами МСУ соответствующих полномочий.',true),
('Стратегическое планирование','Ведомство сравнило фактические показатели стратегии с плановыми, оценило координацию исполнителей и итоги. Что это?','["Первичное целеполагание без оценки","Мониторинг и контроль реализации документов стратегического планирования","Формирование нового субъекта РФ","Создание муниципального округа"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Мониторинг и контроль охватывают ход, итоги и взаимодействие участников.',true),
('Стратегическое планирование','Что характеризует прогноз социально-экономического развития субъекта РФ в 172-ФЗ?','["Научно обоснованные представления об ожидаемых результатах развития субъекта","Только перечень федеральных судей","Результаты муниципальных выборов","Исключительно перечень торговых лицензий"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Региональный прогноз характеризует направления и ожидаемые результаты развития на средне- или долгосрочный период.',true),
('Стратегическое планирование','Каковы характерные элементы плана деятельности федерального органа исполнительной власти по закону?','["Только личные данные работников","Лишь результаты уголовного расследования","Исключительно ставки местных налогов","Цели, направления, индикаторы и планируемые результаты на среднесрочный период"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Пункт 28 включает цели, направления, индикаторы и планируемые промежуточные и итоговые результаты.',true),
('Стратегическое планирование','В чём назначение методического обеспечения стратегического планирования?','["Назначение всех руководителей регионов","Выдача разрешений на судебную деятельность","Разработка и утверждение требований и рекомендаций по подготовке и корректировке стратегических документов","Формирование списка членов Совета Федерации"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Методическое обеспечение связано с требованиями и рекомендациями к разработке и корректировке документов.',true),
('Стратегическое планирование','Кто, согласно закону, разрабатывает и рассматривает документы стратегического планирования?','["Только коммерческие аудиторы","Государственные, региональные, муниципальные и иные установленные законом участники","Исключительно мировые судьи","Только Центральный банк"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Документы стратегического планирования могут подготавливаться, рассматриваться и утверждаться разными участниками публичного управления.',true),
('Стратегическое планирование','В чём состоит прогноз социально-экономического развития России в определении закона?','["Научно обоснованное описание условий, направлений и ожидаемых результатов на средне- либо долгосрочный период","Только изменение налоговой ставки","Исключительно персональные распоряжения служащим","Только отчёт о голосовании депутатов"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Прогноз охватывает внешние и внутренние условия, направления и ожидаемые результаты развития.',true),
('Стратегическое планирование','Власти определили взаимосвязь участников, нормативное, финансовое и информационное обеспечение разработки и контроля стратегий. Что описывается?','["Система лицензирования товаров","Порядок заключения трудового договора","Состав Конституционного Суда РФ","Система стратегического планирования"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Система стратегического планирования — механизм согласованного взаимодействия участников с ресурсным обеспечением.',true),
('Стратегическое планирование','Федеральное министерство готовит отраслевой документ. Что должно быть в нём в соответствии с 172-ФЗ?','["Лишь список сотрудников аппарата","Протокол регионального референдума","Приоритеты, цели, задачи и способы их достижения в соответствующей отрасли","Только сведения о земельных участках"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 3','https://www.consultant.ru/document/cons_doc_LAW_164841/4f41fe599ce341751e4e34dc50a4b676674c1416/','Отраслевой стратегический документ определяет цели и способы их достижения в конкретной сфере.',true),
('Документы стратегического планирования','Ведомство предлагает считать государственную программу России лишь прогнозным документом. Какова правильная классификация по статье 11?','["Документ только муниципального уровня","Документ планирования и программирования федерального уровня","Документ исключительно национальной безопасности","Документ целеполагания по территориальному принципу"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Госпрограммы России отнесены к планированию и программированию на федеральном уровне.',true),
('Документы стратегического планирования','К какой группе федеральных документов стратегического планирования относятся национальные проекты?','["К планированию и программированию","Только к прогнозированию","Только к государственной регистрации","Только к парламентскому контролю"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','С 2024 года национальные проекты прямо перечислены среди документов планирования и программирования.',true),
('Документы стратегического планирования','В какой группе федеральных документов находится стратегия пространственного развития Российской Федерации?','["Мониторинг закупок","Только прогнозирование бюджета","Исключительно программирование на муниципальном уровне","Целеполагание по отраслевому и территориальному принципу"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Статья 11 относит стратегию пространственного развития к целеполаганию по отраслевому и территориальному принципу.',true),
('Документы стратегического планирования','В каком блоке документов находится стратегия научно-технологического развития Российской Федерации?','["В муниципальных программах","В ведомственных должностных регламентах","В федеральных документах целеполагания","В отчётах государственного финансового контроля"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Стратегия научно-технологического развития названа документом целеполагания.',true),
('Документы стратегического планирования','Регион подготовил бюджетный прогноз на долгосрочный период. К какой группе региональных документов он относится?','["К документам только федерального уровня","К документам прогнозирования","К парламентским законопроектам","К документам кадрового делопроизводства"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Бюджетный прогноз субъекта РФ — документ прогнозирования.',true),
('Документы стратегического планирования','К какой группе относится план мероприятий по реализации стратегии субъекта РФ?','["Планирование и программирование субъекта РФ","Исключительно федеральное целеполагание","Только муниципальное прогнозирование","Внутренний регламент политической партии"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','План мероприятий по реализации региональной стратегии — документ планирования и программирования.',true),
('Документы стратегического планирования','Может ли муниципальная программа быть документом стратегического планирования?','["Нет, программы существуют только в федеральных органах","Нет, в законе упомянуты исключительно стратегии","Нет, муниципальные образования не участвуют в стратегическом планировании","Да, она прямо названа законом"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Муниципальные программы прямо включены в перечень статьи 11.',true),
('Документы стратегического планирования','Кто координирует разработку и реализацию документов стратегического планирования на федеральном уровне по вопросам своего ведения?','["Только федеральные суды","Исключительно муниципальные администрации","Президент РФ и Правительство РФ","Только политические партии"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Статья 11 предусматривает координацию Президентом и Правительством по компетенции.',true),
('Документы стратегического планирования','Считается ли ежегодное послание Президента Федеральному Собранию документом федерального целеполагания?','["Нет","Да","Только если оно принято отдельным законом","Только после одобрения всех субъектов РФ"]'::jsonb,1,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Послание Президента включено в документы целеполагания.',true),
('Документы стратегического планирования','Может ли научная организация привлекаться к подготовке документа стратегического планирования?','["Да, с соблюдением требований об охраняемой законом тайне","Нет, участвуют лишь государственные служащие","Только при назначении судом","Нет, это запрещено независимо от характера документа"]'::jsonb,0,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Часть 7 статьи 11 допускает участие общественных, научных и иных организаций с оговоркой о тайне.',true),
('Документы стратегического планирования','Чем определяется порядок разработки муниципальных стратегических документов в пределах требований 172-ФЗ?','["Исключительно приказом территориальной полиции","Решением федерального арбитражного суда","Только регламентом государственной корпорации","Муниципальными нормативными правовыми актами и компетенцией органов местного самоуправления"]'::jsonb,3,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Пункт 6 статьи 11 относит муниципальный порядок к органам МСУ, определённым муниципальными НПА.',true),
('Документы стратегического планирования','Входит ли бюджетный прогноз муниципального образования на долгосрочный период в число документов стратегического планирования?','["Нет","Только у городов федерального значения","Да","Только при наличии природных ресурсов"]'::jsonb,2,'Федеральный закон от 28.06.2014 № 172-ФЗ','статья 11','https://www.consultant.ru/document/cons_doc_LAW_164841/fe7140d7cfc6c641ae322fe648d99702d8b2a8f1/','Муниципальный бюджетный прогноз прямо указан в пункте 5 статьи 11.',true),
('Региональная публичная власть','Региональный акт предлагает скрывать всю информацию о деятельности публичных органов. Какому принципу 414-ФЗ это противоречит?','["Только принципу территориального деления","Обеспечению гласности и доступа к информации","Исключительно свободе предпринимательства","Положению о государственной регистрации компаний"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 2','https://www.consultant.ru/document/cons_doc_LAW_404070/b1cb0c1385c89e2396c3f614f4158981032a000e/','Статья 2 закрепляет гласность деятельности публичных органов и доступ к информации.',true),
('Региональная публичная власть','Регион и муниципалитет отказываются взаимодействовать по общему вопросу публичного управления. Какому принципу это противоречит?','["Согласованному функционированию и взаимодействию уровней публичной власти","Исключительно принципу коммерческой тайны","Принципу независимости частных банков","Правилу о ежегодной аттестации"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 2','https://www.consultant.ru/document/cons_doc_LAW_404070/b1cb0c1385c89e2396c3f614f4158981032a000e/','Принцип согласованного взаимодействия действует на федеральном, региональном и муниципальном уровнях.',true),
('Региональная публичная власть','Закон субъекта предполагает передачу муниципалитету полномочия без необходимого финансового обеспечения. Какой принцип необходимо учитывать?','["Принцип единой ставки налога для всех отраслей","Исключительно принцип свободной торговли","Правило об обязательном федеральном референдуме","Гарантии финансового обеспечения передаваемых полномочий"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 2','https://www.consultant.ru/document/cons_doc_LAW_404070/b1cb0c1385c89e2396c3f614f4158981032a000e/','Статья 2 закрепляет гарантии финансового обеспечения полномочий вследствие их разграничения.',true),
('Региональная публичная власть','Допускается ли участие общественного контроля наряду с государственным и парламентским в контроле деятельности публичных органов?','["Нет","Только за федеральными министерствами","Да","Только после суда"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 2','https://www.consultant.ru/document/cons_doc_LAW_404070/b1cb0c1385c89e2396c3f614f4158981032a000e/','Статья 2 перечисляет государственный, парламентский и общественный контроль.',true),
('Региональная публичная власть','Каким принципом руководствуются региональные органы публичной власти при обеспечении прав граждан?','["Приоритет интересов только должностных лиц","Обеспечение соблюдения и защиты прав и свобод человека и гражданина","Обязательное ограничение всех жалоб","Приоритет частной выгоды перед законом"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 2','https://www.consultant.ru/document/cons_doc_LAW_404070/b1cb0c1385c89e2396c3f614f4158981032a000e/','Защита прав и свобод человека и гражданина — первый принцип статьи 2.',true),
('Региональная публичная власть','Может ли региональный закон предусматривать дистанционное участие депутатов в заседаниях законодательного органа субъекта РФ?','["Да, статья 2 допускает соответствующее регулирование","Нет, федеральный закон запрещает дистанционное участие","Только по решению Центрального банка","Лишь в виде консультаций без заседаний"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 2','https://www.consultant.ru/document/cons_doc_LAW_404070/b1cb0c1385c89e2396c3f614f4158981032a000e/','Часть 2 статьи 2 допускает региональное регулирование дистанционного участия.',true),
('Региональная публичная власть','Какой принцип требует учитывать федеральную, региональную и муниципальную компетенцию при принятии решения?','["Абсолютное единоначалие всех органов","Полная отмена муниципальных полномочий","Передача всех функций коммерческим организациям","Разграничение предметов ведения и полномочий между уровнями публичной власти"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 2','https://www.consultant.ru/document/cons_doc_LAW_404070/b1cb0c1385c89e2396c3f614f4158981032a000e/','Разграничение предметов ведения и полномочий прямо предусмотрено статьёй 2.',true),
('Региональная публичная власть','Является ли самостоятельность местного самоуправления в пределах полномочий принципом деятельности единой системы публичной власти?','["Нет","Только для городов федерального значения","Да","Только для муниципалитетов с профицитным бюджетом"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 2','https://www.consultant.ru/document/cons_doc_LAW_404070/b1cb0c1385c89e2396c3f614f4158981032a000e/','Закон признаёт и гарантирует местное самоуправление и самостоятельность в пределах полномочий.',true),
('Региональная публичная власть','Какая цель прямо названа для взаимодействия органов публичной власти внутри субъекта РФ?','["Ликвидация всех местных бюджетов","Условия устойчивого и комплексного социально-экономического развития территории","Избрание руководителей всех федеральных агентств","Ограничение деятельности научных организаций"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 2','https://www.consultant.ru/document/cons_doc_LAW_404070/b1cb0c1385c89e2396c3f614f4158981032a000e/','Часть 2 статьи 2 связывает взаимодействие органов с комплексным развитием территории.',true),
('Региональная публичная власть','Допускается ли дистанционное взаимодействие органов публичной власти в субъекте на основании регионального регулирования?','["Да","Нет","Только через федеральный суд","Только при военном положении"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 2','https://www.consultant.ru/document/cons_doc_LAW_404070/b1cb0c1385c89e2396c3f614f4158981032a000e/','Статья 2 допускает установление порядка дистанционного взаимодействия региональными НПА.',true),
('Полномочия органов субъектов РФ','В систему органов государственной власти субъекта РФ включили только парламент и губернатора, исключив правительство региона. Соответствует ли это перечню 414-ФЗ?','["Да, исполнительный орган необязателен","Нет, в систему входят исключительно суды","Да, если регион небольшой","Нет, высший исполнительный орган также входит в систему"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_404070/dd1341b06a7d5aff370204a361fa7a537de31f00/','Статья 4 включает законодательный орган, высшее должностное лицо и высший исполнительный орган.',true),
('Полномочия органов субъектов РФ','Может ли субъект РФ образовывать иные государственные органы в соответствии со своей конституцией или уставом?','["Нет","Только международным договором","Да","Только решением Центральной избирательной комиссии"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_404070/dd1341b06a7d5aff370204a361fa7a537de31f00/','Часть 2 статьи 4 допускает образование иных региональных госорганов на основании конституции (устава).',true),
('Полномочия органов субъектов РФ','Кто обязан обеспечивать соответствие региональных нормативных актов Конституции РФ и федеральным законам?','["Только общественные объединения","Органы государственной власти субъекта Российской Федерации","Исключительно федеральные суды","Только главные редакторы региональных СМИ"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_404070/dd1341b06a7d5aff370204a361fa7a537de31f00/','Часть 1 статьи 4 обязывает региональные органы обеспечивать соответствие их НПА федеральному праву.',true),
('Полномочия органов субъектов РФ','При передаче федеральных полномочий исполнительному органу субъекта вправе ли федеральный орган участвовать в назначении регионального должностного лица в случаях, предусмотренных ФЗ?','["Да","Нет","Только по решению представительного органа муниципалитета","Только если орган занимается спортом"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_404070/dd1341b06a7d5aff370204a361fa7a537de31f00/','Часть 3 статьи 4 допускает участие федеральных органов в формировании органов субъекта, исполняющих переданные полномочия.',true),
('Полномочия органов субъектов РФ','Можно ли расширить перечень региональных органов исполнительной власти, для руководителей которых применяется предусмотренное частью 4 статьи 4 согласование, простым распоряжением губернатора?','["Да, без каких-либо ограничений","Да, достаточно ведомственного письма","Только решением муниципального совета","Нет, перечень исчерпывающий и меняется федеральным законом"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_404070/dd1341b06a7d5aff370204a361fa7a537de31f00/','Часть 5 статьи 4 закрепляет исчерпывающий перечень, изменяемый федеральным законом.',true),
('Полномочия органов субъектов РФ','Могут ли федеральные органы участвовать в согласовании назначения руководителя регионального финансового органа в случаях, установленных законодательством?','["Нет, финансами занимаются исключительно муниципалитеты","Нет, это исключено для всех региональных ведомств","Да","Только по решению общественной палаты"]'::jsonb,2,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_404070/dd1341b06a7d5aff370204a361fa7a537de31f00/','Часть 4 статьи 4 предусматривает согласование для отдельных сфер, включая финансы.',true),
('Полномочия органов субъектов РФ','Должны ли проекты федеральных законов, меняющих перечень региональных ведомств из частей 4–5 статьи 4, предварительно обсуждаться рабочими органами Государственного Совета?','["Нет","Да","Только если затрагивают военную службу","Только по решению губернатора"]'::jsonb,1,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_404070/dd1341b06a7d5aff370204a361fa7a537de31f00/','Часть 6 статьи 4 предусматривает предварительное обсуждение таких законопроектов.',true),
('Полномочия органов субъектов РФ','Какие гарантии должны обеспечивать региональные органы в отношении выборов в органы власти субъекта и местного самоуправления?','["Своевременное назначение и периодическое проведение выборов","Только назначение выборов без каких-либо сроков","Отказ от участия граждан через представителей","Полную отмену муниципальных выборов"]'::jsonb,0,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_404070/dd1341b06a7d5aff370204a361fa7a537de31f00/','Часть 7 статьи 4 упоминает гарантии своевременности и периодичности выборов.',true),
('Полномочия органов субъектов РФ','Какими актами устанавливаются полномочия органов государственной власти субъекта РФ?','["Только внутренними письмами ведомств","Исключительно распоряжением главы муниципалитета","Только программами политических партий","Конституцией РФ, федеральными законами, конституцией (уставом) и законами субъекта"]'::jsonb,3,'Федеральный закон от 21.12.2021 № 414-ФЗ','статья 4','https://www.consultant.ru/document/cons_doc_LAW_404070/dd1341b06a7d5aff370204a361fa7a537de31f00/','Часть 9 статьи 4 определяет многоуровневую нормативную основу полномочий.',true),
('Государственная гражданская служба','Руководитель поручил служащему совершить действие, которое тот обоснованно считает незаконным. Какой первый предусмотренный законом шаг?','["Немедленно исполнить без возражений","Объявить поручение законным задним числом","Представить письменное обоснование неправомерности с указанием норм закона","Самостоятельно изменить законодательство"]'::jsonb,2,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Часть 2 статьи 15 предписывает письменное обоснование неправомерности поручения.',true),
('Государственная гражданская служба','Руководитель письменно подтвердил поручение, нарушающее закон. Как обязан действовать гражданский служащий?','["Исполнить независимо от последствий","Отказаться от его исполнения","Передать исполнение подчинённому без объяснений","Скрыть документы, подтверждающие незаконность"]'::jsonb,1,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','При письменном подтверждении неправомерного поручения служащий обязан отказаться от исполнения.',true),
('Государственная гражданская служба','Кто несёт установленную законом ответственность при исполнении неправомерного поручения?','["И исполнивший служащий, и отдавший поручение руководитель","Исключительно заявитель","Только работник кадровой службы","Никто, если поручение письменно"]'::jsonb,0,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Часть 3 статьи 15 предусматривает ответственность обоих участников.',true),
('Государственная гражданская служба','Обязан ли гражданский служащий исполнять поручения руководителя, выходящие за пределы полномочий руководителя?','["Да, если поручение устное","Да, если это ускоряет работу","Да, при отсутствии служебной записки","Нет"]'::jsonb,3,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Подпункт 3 части 1 ограничивает исполнение поручений пределами законных полномочий руководителя.',true),
('Государственная гражданская служба','Ведомство просит служащего раскрыть полученные на работе сведения о частной жизни гражданина без законного основания. Как должен поступить служащий?','["Разместить сведения в открытой группе","Передать данные знакомым без оформления","Сохранить конфиденциальность таких сведений","Опубликовать их на личном сайте"]'::jsonb,2,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 7 части 1 требует не разглашать охраняемые сведения, включая данные о частной жизни.',true),
('Государственная гражданская служба','Должен ли гражданский служащий беречь государственное имущество, переданное ему для работы?','["Нет","Да","Только после ежегодной инвентаризации","Только если стоимость выше установленного минимума"]'::jsonb,1,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 8 части 1 прямо устанавливает обязанность беречь государственное имущество.',true),
('Государственная гражданская служба','Чиновник узнал о личной заинтересованности, способной вызвать конфликт интересов. Что он обязан сделать?','["Сообщить представителю нанимателя и принять меры предотвращения конфликта","Продолжить работу без уведомления","Передать проблему только в СМИ","Считать конфликт отсутствующим, пока не получен доход"]'::jsonb,0,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 12 части 1 требует уведомления и принятия мер.',true),
('Государственная гражданская служба','Служащий нарушает права граждан, исполняя служебное распоряжение. Какая норма определяет его обязанность?','["Защищать исключительно служебные интересы ведомства","Принимать обращения только от организаций","Ставить ведомственный план выше прав граждан","Соблюдать при исполнении обязанностей права и законные интересы граждан и организаций"]'::jsonb,3,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 4 части 1 требует соблюдения прав и законных интересов граждан и организаций.',true),
('Государственная гражданская служба','Допускает ли закон игнорировать служебный распорядок государственного органа по личному усмотрению служащего?','["Да, вне зависимости от должности","Да, если у него большой стаж","Нет","Да, если он работает с документами"]'::jsonb,2,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 5 части 1 обязывает соблюдать служебный распорядок.',true),
('Государственная гражданская служба','Служащий отказывается поддерживать профессиональный уровень, необходимый для выполнения обязанностей. Соответствует ли это закону?','["Да, квалификация нужна только при поступлении","Нет, необходимый профессиональный уровень должен поддерживаться","Да, если есть классный чин","Да, если работодатель не требует отчёта"]'::jsonb,1,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 6 части 1 содержит соответствующую обязанность.',true),
('Государственная гражданская служба','Какой документ определяет исполнение должностных обязанностей гражданского служащего?','["Должностной регламент","Только рекламный план учреждения","Программа региональной партии","Соглашение о местном референдуме"]'::jsonb,0,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 2 части 1 устанавливает исполнение обязанностей в соответствии с должностным регламентом.',true),
('Государственная гражданская служба','Гражданский служащий получил сведения об изменениях в своей анкете, не внесённых по решению нанимателя. Что требуется по закону?','["Ничего не сообщать до конца срока службы","Передать информацию только частному работодателю","Опубликовать сообщение в социальной сети","Письменно сообщить представителю нанимателя"]'::jsonb,3,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 13 части 1 требует письменного сообщения об изменениях сведений анкеты.',true),
('Государственная гражданская служба','Вправе ли гражданский служащий сознательно нарушать установленные федеральными законами служебные запреты ради экономии времени?','["Да, при срочном бюджетном поручении","Да, если никто не подал жалобу","Нет","Да, по устной договорённости с коллегами"]'::jsonb,2,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 11 части 1 требует соблюдения ограничений и запретов.',true),
('Государственная гражданская служба','Может ли гражданский служащий замещать руководящую должность высшей группы и представлять интересы служащих в выборном профсоюзном органе того же органа в течение такого замещения?','["Да, без ограничений","Нет, для предотвращения конфликта интересов это ограничено","Да, если избран большинством коллег","Да, если нет служебных споров"]'::jsonb,1,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Часть 4 статьи 15 устанавливает указанное ограничение для высших руководителей.',true),
('Государственная гражданская служба','Гражданский служащий получил вид на жительство иностранного государства. Должен ли он письменно сообщить об этом представителю нанимателя в установленный законом срок?','["Да","Нет","Только по запросу прокуратуры","Только при прохождении переаттестации"]'::jsonb,0,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 10 части 1 устанавливает письменное уведомление в установленный срок.',true),
('Государственная гражданская служба','Какой из перечисленных документов служащий обязан соблюдать при исполнении своих обязанностей?','["Только локальную инструкцию без учёта закона","Только постановления муниципального совета","Исключительно документы политических объединений","Конституцию РФ, федеральные и региональные нормативные правовые акты"]'::jsonb,3,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 1 части 1 закрепляет обязанность соблюдать нормы разных уровней.',true),
('Государственная гражданская служба','Обязательно ли государственному гражданскому служащему представлять предусмотренные законом сведения о себе и членах семьи в установленном порядке?','["Нет","Только перед увольнением","Да","Исключительно по решению собрания работников"]'::jsonb,2,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Пункт 9 части 1 предусматривает обязанность представлять требуемые законом сведения.',true),
('Государственная гражданская служба','Можно ли считать, что письменная форма незаконного поручения освобождает исполнителя от ответственности?','["Да, всегда","Нет","Да, если документ подписан начальником отдела","Да, если служащий сохранил копию"]'::jsonb,1,'Федеральный закон от 27.07.2004 № 79-ФЗ','статья 15','https://www.consultant.ru/document/cons_doc_LAW_48601/dae59c94f974cf5b00f234ee99cc80376aa20d8e/','Части 2–3 статьи 15 не допускают исполнения неправомерного поручения и предусматривают ответственность.',true)
